 15 │ /// A response's decoded `result`, tagged with the wire-arrival order it was read in —
 16 │ /// see the module doc on [`Client::request`] for why that matters.
 17 │ #[derive(Debug, Clone)]
 18 │ pub struct TaggedResponse {
 19 │     pub value: serde_json::Value,
 20 │     pub seq: u64,
 21 │ }
 22 │ 
 23 │ struct ClientInner {
 24 │     stdin: AsyncMutex<ChildStdin>,
 25 │     pending: DashMap<u64, oneshot::Sender<Result<TaggedResponse, TscClientError>>>,
 26 │     next_id: AtomicU64,
 27 │     /// Wire-arrival order, stamped by the reader task as each frame is decoded — not
 28 │     /// issue order, not wall clock. Lets a caller mechanically check whether a query's
 29 │     /// answer could reflect an update it already saw acknowledged
 30 │     /// (`answer.seq > update_ack.seq`), the concrete slice of freshness tracking this
 31 │     /// crate can build without the real (still-churning) `updateSnapshot` wire shape.
 32 │     next_seq: AtomicU64,
 33 │     notifications: AsyncMutex<Option<mpsc::UnboundedReceiver<Notification>>>,
 34 │ }
 35 │ 
 36 │ impl ClientInner {
 37 │     fn dispatch(&self, body: &[u8], seq: u64, notif_tx: &mpsc::UnboundedSender<Notification>) {
 38 │         match protocol::parse_incoming(body) {
 39 │             Ok(IncomingMessage::Response(response)) => {
 40 │                 if let Some((_, tx)) = self.pending.remove(&response.id.0) {
 41 │                     let result = if let Some(error) = response.error {
 42 │                         Err(TscClientError::RpcError { code: error.code, message: error.message, data: error.data })
 43 │                     } else {
 44 │                         Ok(TaggedResponse { value: response.result.unwrap_or(serde_json::Value::Null), seq })
 45 │                     };
 46 │                     // A dropped receiver means the caller already gave up (e.g. timed
 47 │                     // out) — nothing left to deliver to.
 48 │                     let _ = tx.send(result);
 49 │                 }
 50 │             }
 51 │             Ok(IncomingMessage::Notification(notification)) => {
 52 │                 let _ = notif_tx.send(Notification { method: notification.method, params: notification.params });
 53 │             }
 54 │             Err(source) => {
 55 │                 // A malformed *body* doesn't desync the stream — the declared
 56 │                 // Content-Length was honored — so the session stays alive; this one
 57 │                 // frame is just unusable.
 58 │                 tracing::warn!("dropping unparsable tsc frame: {source}");
 59 │             }
 60 │         }
 61 │     }
 62 │ 
 63 │     /// Delivers one session-ending failure to every caller still waiting on a
 64 │     /// response. `TscClientError` is cheaply `Clone`, so every waiter gets its own
 65 │     /// full copy, not a shared reference they'd have to reason about outliving.
 66 │     fn fail_all_pending(&self, err: &TscClientError) {
 67 │         let ids: Vec<u64> = self.pending.iter().map(|entry| *entry.key()).collect();
 68 │         for id in ids {
 69 │             if let Some((_, tx)) = self.pending.remove(&id) {
 70 │                 let _ = tx.send(Err(err.clone()));
 71 │             }
 72 │         }
 73 │     }
 74 │ }
