 21 │ pub struct SupervisorConfig {
 22 │     /// Path to the `tsc` binary, e.g. `node_modules/typescript/bin/tsc` — resolving
 23 │     /// that path is the caller's job, not this crate's.
 24 │     pub tsc_path: Utf8PathBuf,
 25 │     /// Passed as `tsc --api --async --cwd <cwd>`.
 26 │     pub cwd: Utf8PathBuf,
 27 │     /// `tsc_path`'s adjacent `package.json` "version" must be one of these, checked
 28 │     /// before every spawn. The protocol has no version handshake (ADR 0006), so this
 29 │     /// is the whole mechanism — the caller decides which exact build(s) are pinned.
 30 │     pub expected_versions: &'static [&'static str],
 31 │     pub handshake_timeout: Duration,
 32 │     pub max_frame_bytes: usize,
 33 │     /// Extra environment variables for the spawned process. Empty for real use; tests
 34 │     /// use this to pick a `fake-tsc` scenario via `FAKE_TSC_SCENARIO`.
 35 │     pub extra_env: Vec<(String, String)>,
 36 │ }
