  1 │ //! A scenario-driven fake `tsc --api` process for the Lifecycle-gate test suite.
  2 │ //! Scenario is picked via the `FAKE_TSC_SCENARIO` env var (env, not argv, matching
  3 │ //! `crates/cli/src/config.rs`'s precedent for test/caller-controlled input):
  4 │ //! `echo` (default), `never_respond`, `hang_after_n:<N>`, `exit_after:<N>:<code>`,
  5 │ //! `crash_immediately:<code>`, `garbage_bytes`, `bad_content_length`,
  6 │ //! `oversized_frame:<N>`, `truncated_body`, `reorder_ack`, `shutdown_slow:<ms>`.
  7 │ //!
  8 │ //! Valid-frame scenarios are built on this crate's own `transport::{ContentLengthDecoder,
  9 │ //! write_frame}`, so this fixture can't drift from what the real client parses;
 10 │ //! bad-frame scenarios intentionally hand-write raw bytes instead.
 11 │ 
 12 │ use std::time::Duration;
 13 │ 
 14 │ use oxc_react_docgen_tsc_client::transport::{write_frame, ContentLengthDecoder, DEFAULT_MAX_FRAME_BYTES};
 15 │ use tokio::io::AsyncWriteExt;
 16 │ use tokio_stream::StreamExt;
 17 │ use tokio_util::codec::FramedRead;
 18 │ 
 19 │ type Requests = FramedRead<tokio::io::Stdin, ContentLengthDecoder>;
 20 │ 
 21 │ fn requests() -> Requests {
 22 │     FramedRead::new(tokio::io::stdin(), ContentLengthDecoder::new(DEFAULT_MAX_FRAME_BYTES))
 23 │ }
 24 │ 
 25 │ #[tokio::main]
 26 │ async fn main() {
 27 │     let scenario = std::env::var("FAKE_TSC_SCENARIO").unwrap_or_else(|_| "echo".to_string());
 28 │     let mut parts = scenario.splitn(3, ':');
 29 │     let name = parts.next().unwrap_or("echo");
 30 │     let arg1 = parts.next();
 31 │     let arg2 = parts.next();
 32 │ 
 33 │     match name {
 34 │         "never_respond" => never_respond().await,
 35 │         "hang_after_n" => hang_after_n(arg1.and_then(|s| s.parse().ok()).unwrap_or(0)).await,
 36 │         "exit_after" => {
 37 │             exit_after(arg1.and_then(|s| s.parse().ok()).unwrap_or(0), arg2.and_then(|s| s.parse().ok()).unwrap_or(1))
 38 │                 .await;
 39 │         }
 40 │         "crash_immediately" => std::process::exit(arg1.and_then(|s| s.parse().ok()).unwrap_or(1)),
 41 │         "garbage_bytes" => garbage_bytes().await,
 42 │         "bad_content_length" => bad_content_length().await,
 43 │         "oversized_frame" => oversized_frame(arg1.and_then(|s| s.parse().ok()).unwrap_or(usize::MAX)).await,
 44 │         "truncated_body" => truncated_body().await,
 45 │         "reorder_ack" => reorder_ack().await,
 46 │         "shutdown_slow" => shutdown_slow(arg1.and_then(|s| s.parse().ok()).unwrap_or(10_000)).await,
 47 │         _ => echo().await,
 48 │     }
 49 │ }
 50 │ 
 51 │ fn request_id(request: &serde_json::Value) -> serde_json::Value {
 52 │     request.get("id").cloned().unwrap_or(serde_json::Value::Null)
 53 │ }
 54 │ 
 55 │ async fn read_request(reader: &mut Requests) -> Option<serde_json::Value> {
 56 │     match reader.next().await {
 57 │         Some(Ok(body)) => serde_json::from_slice(&body).ok(),
 58 │         _ => None,
 59 │     }
 60 │ }
 61 │ 
 62 │ async fn respond<W: tokio::io::AsyncWrite + Unpin>(writer: &mut W, id: &serde_json::Value, result: serde_json::Value) {
 63 │     let body = serde_json::json!({ "id": id, "result": result });
 64 │     if let Ok(bytes) = serde_json::to_vec(&body) {
 65 │         let _ = write_frame(writer, &bytes).await;
 66 │     }
 67 │ }
 68 │ 
 69 │ async fn respond_error<W: tokio::io::AsyncWrite + Unpin>(
 70 │     writer: &mut W,
 71 │     id: &serde_json::Value,
 72 │     code: i64,
 73 │     message: &str,
 74 │ ) {
 75 │     let body = serde_json::json!({ "id": id, "error": { "code": code, "message": message } });
 76 │     if let Ok(bytes) = serde_json::to_vec(&body) {
 77 │         let _ = write_frame(writer, &bytes).await;
 78 │     }
 79 │ }
 80 │ 
 81 │ /// Baseline: echoes `params` back as `result.echo`, or replies with an `error` object
 82 │ /// when `params.fail` is `true` — used to test that one failing call doesn't affect a
 83 │ /// concurrently in-flight sibling (partial project failure).
 84 │ async fn echo() {
 85 │     let mut reader = requests();
 86 │     let mut stdout = tokio::io::stdout();
 87 │     while let Some(request) = read_request(&mut reader).await {
 88 │         let id = request_id(&request);
 89 │         let params = request.get("params").cloned().unwrap_or(serde_json::Value::Null);
 90 │         if params.get("fail").and_then(serde_json::Value::as_bool).unwrap_or(false) {
 91 │             respond_error(&mut stdout, &id, -32000, "requested failure").await;
 92 │         } else {
 93 │             respond(&mut stdout, &id, serde_json::json!({ "echo": params })).await;
 94 │         }
 95 │     }
 96 │ }
