  1 │ use std::process::Stdio;
  2 │ use std::sync::Arc;
  3 │ use std::time::{Duration, Instant};
  4 │ 
  5 │ use camino::{Utf8Path, Utf8PathBuf};
  6 │ use tokio::io::AsyncBufReadExt;
  7 │ use tokio::process::{Child, Command};
  8 │ 
  9 │ use crate::client::{Client, TaggedResponse};
 10 │ use crate::error::TscClientError;
 11 │ 
 12 │ const DEFAULT_HANDSHAKE_TIMEOUT: Duration = Duration::from_secs(10); // measured 33-72ms; generous headroom
 13 │ const SHUTDOWN_GRACE: Duration = Duration::from_secs(2);
 14 │ const MAX_RESTARTS: u32 = 3;
 15 │ const RESTART_WINDOW: Duration = Duration::from_secs(60);
 16 │ const BACKOFF_STEPS: [Duration; 3] =
 17 │     [Duration::from_millis(200), Duration::from_millis(400), Duration::from_millis(800)];
 18 │ const BACKOFF_MAX: Duration = Duration::from_secs(5);
 19 │ 
 20 │ #[derive(Debug, Clone)]
 21 │ pub struct SupervisorConfig {
 22 │     /// Path to the `tsc` binary, e.g. `node_modules/typescript/bin/tsc` — resolving
 23 │     /// that path is the caller's job, not this crate's.
 24 │     pub tsc_path: Utf8PathBuf,
 25 │     /// Passed as `tsc --api --async --cwd <cwd>`.
 26 │     pub cwd: Utf8PathBuf,
 27 │     /// `tsc_path`'s adjacent `package.json` "version" must be one of these, checked
 28 │     /// before every spawn. The protocol has no version handshake (ADR 0006), so this
 29 │     /// is the whole mechanism — the caller decides which exact build(s) are pinned.
 30 │     pub expected_versions: &'static [&'static str],
 31 │     pub handshake_timeout: Duration,
 32 │     pub max_frame_bytes: usize,
 33 │     /// Extra environment variables for the spawned process. Empty for real use; tests
 34 │     /// use this to pick a `fake-tsc` scenario via `FAKE_TSC_SCENARIO`.
 35 │     pub extra_env: Vec<(String, String)>,
 36 │ }
 37 │ 
 38 │ impl SupervisorConfig {
 39 │     pub fn new(tsc_path: Utf8PathBuf, cwd: Utf8PathBuf, expected_versions: &'static [&'static str]) -> Self {
 40 │         Self {
 41 │             tsc_path,
 42 │             cwd,
 43 │             expected_versions,
 44 │             handshake_timeout: DEFAULT_HANDSHAKE_TIMEOUT,
 45 │             max_frame_bytes: crate::transport::DEFAULT_MAX_FRAME_BYTES,
 46 │             extra_env: Vec::new(),
 47 │         }
 48 │     }
 49 │ }
 50 │ 
 51 │ fn check_version(tsc_path: &Utf8Path, expected: &'static [&'static str]) -> Result<(), TscClientError> {
 52 │     let reason_at = |reason: String| TscClientError::VersionCheckFailed { path: tsc_path.to_owned(), reason };
 53 │ 
 54 │     let Some(package_json) =
 55 │         tsc_path.parent().and_then(|bin_dir| bin_dir.parent()).map(|pkg_dir| pkg_dir.join("package.json"))
 56 │     else {
 57 │         return Err(reason_at("tsc_path has no grandparent directory to find package.json in".to_string()));
 58 │     };
 59 │ 
 60 │     let contents = std::fs::read_to_string(&package_json)
 61 │         .map_err(|source| reason_at(format!("reading {package_json}: {source}")))?;
 62 │     let value: serde_json::Value =
 63 │         serde_json::from_str(&contents).map_err(|source| reason_at(format!("parsing {package_json}: {source}")))?;
 64 │     let Some(found) = value.get("version").and_then(|v| v.as_str()) else {
 65 │         return Err(reason_at(format!("{package_json} has no \"version\" string")));
 66 │     };
 67 │ 
 68 │     if expected.contains(&found) {
 69 │         Ok(())
 70 │     } else {
 71 │         Err(TscClientError::UnsupportedVersion { path: tsc_path.to_owned(), found: found.to_string(), expected })
 72 │     }
 73 │ }
 74 │ 
 75 │ fn spawn_stderr_drain(stderr: tokio::process::ChildStderr) {
 76 │     // Must be continuously drained: an unread stderr pipe fills its OS buffer and can
 77 │     // deadlock the child. Logged at debug, not warn — tsc's own diagnostic chatter
 78 │     // isn't inherently an error, but it's valuable when a crash needs explaining.
 79 │     tokio::spawn(async move {
 80 │         let mut lines = tokio::io::BufReader::new(stderr).lines();
 81 │         while let Ok(Some(line)) = lines.next_line().await {
 82 │             tracing::debug!(target: "tsc_client::stderr", "{line}");
 83 │         }
 84 │     });
 85 │ }
 86 │ 
 87 │ /// Spawns one `tsc --api` process and wires up its transport. Split out from
 88 │ /// `Supervisor::spawn`/`restart` so a restart can replace the process/client/reader
 89 │ /// triple without losing the restart-attempt bookkeeping a fresh `Supervisor` would
 90 │ /// otherwise reset.
 91 │ async fn spawn_process(
 92 │     config: &SupervisorConfig,
 93 │ ) -> Result<(Child, Client, tokio::task::JoinHandle<TscClientError>), TscClientError> {
 94 │     check_version(&config.tsc_path, config.expected_versions)?;
 95 │ 
 96 │     let mut command = Command::new(config.tsc_path.as_std_path());
 97 │     command.arg("--api").arg("--async").arg("--cwd").arg(config.cwd.as_std_path());
 98 │     command.stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped());
 99 │     command.envs(config.extra_env.iter().map(|(k, v)| (k.as_str(), v.as_str())));
100 │     // Best-effort fallback if `Supervisor::shutdown` is never called — this alone
101 │     // doesn't guarantee reaping (Drop can't await), only `.shutdown()` does.
102 │     command.kill_on_drop(true);
103 │ 
104 │     let mut child = command
105 │         .spawn()
106 │         .map_err(|source| TscClientError::SpawnFailed { path: config.tsc_path.clone(), source: Arc::new(source) })?;
107 │ 
108 │     let Some(stdin) = child.stdin.take() else { unreachable!("stdin is None despite Stdio::piped()") };
109 │     let Some(stdout) = child.stdout.take() else { unreachable!("stdout is None despite Stdio::piped()") };
110 │     let Some(stderr) = child.stderr.take() else { unreachable!("stderr is None despite Stdio::piped()") };
111 │ 
112 │     spawn_stderr_drain(stderr);
113 │     let (client, reader_handle) = Client::connect(stdin, stdout, config.max_frame_bytes);
114 │ 
115 │     Ok((child, client, reader_handle))
116 │ }
117 │ 
118 │ /// Owns one `tsc --api` child process across its lifetime: spawn, version check,
119 │ /// crash-triggered restart (bounded, to avoid a restart storm), and shutdown/reaping.
120 │ pub struct Supervisor {
121 │     child: Child,
122 │     client: Client,
123 │     reader_handle: tokio::task::JoinHandle<TscClientError>,
124 │     config: SupervisorConfig,
125 │     restart_attempts: Vec<Instant>,
126 │     /// Set once a restart-storm cap is hit. Terminal — every later call short-circuits
127 │     /// without touching the process again.
128 │     failed: bool,
129 │ }
130 │ 
131 │ impl Supervisor {
132 │     pub async fn spawn(config: SupervisorConfig) -> Result<Self, TscClientError> {
133 │         let (child, client, reader_handle) = spawn_process(&config).await?;
134 │         Ok(Self { child, client, reader_handle, config, restart_attempts: Vec::new(), failed: false })
135 │     }
136 │ 
137 │     /// The current session's low-level handle. Cheap to clone. After a
138 │     /// supervisor-driven restart, `Client` clones obtained *before* the restart are
139 │     /// permanently `SessionClosed` — call this again to get the live one.
140 │     pub fn client(&self) -> Client {
141 │         self.client.clone()
142 │     }
143 │ 
144 │     /// True while the current process's reader task is still running and the
145 │     /// supervisor hasn't permanently failed. A crash between calls to this method and
146 │     /// the next `request()` is still possible — this is a snapshot, not a guarantee.
147 │     pub fn is_alive(&self) -> bool {
148 │         !self.reader_handle.is_finished() && !self.failed
149 │     }
150 │ 
151 │     /// Sends a request through the current session. On `Crashed`, restarts once (if
152 │     /// the restart budget allows) and retries the same call once before giving up —
153 │     /// a request lost to a crash is never silently replayed more than that.
154 │     pub async fn request(
155 │         &mut self,
156 │         method: &str,
157 │         params: serde_json::Value,
158 │         deadline: Duration,
159 │     ) -> Result<TaggedResponse, TscClientError> {
160 │         if self.failed {
161 │             return Err(TscClientError::RestartStormDetected {
162 │                 attempts: self.restart_attempts.len() as u32,
163 │                 window: RESTART_WINDOW,
164 │             });
165 │         }
166 │ 
167 │         match self.client.request(method, params.clone(), deadline).await {
168 │             // A write failure to the child's stdin is, in practice, always the pipe
169 │             // closing because the child exited — treated the same as a crash observed
170 │             // through the read side, so a restart gets attempted either way.
171 │             Err(TscClientError::Crashed { .. } | TscClientError::Write(_)) => {
172 │                 self.restart().await?;
173 │                 self.client.request(method, params, deadline).await
174 │             }
175 │             other => other,
176 │         }
177 │     }
178 │ 
179 │     async fn restart(&mut self) -> Result<(), TscClientError> {
180 │         let now = Instant::now();
181 │         self.restart_attempts.retain(|attempt| now.duration_since(*attempt) < RESTART_WINDOW);
182 │ 
183 │         if self.restart_attempts.len() as u32 >= MAX_RESTARTS {
184 │             self.failed = true;
185 │             return Err(TscClientError::RestartStormDetected {
186 │                 attempts: self.restart_attempts.len() as u32,
187 │                 window: RESTART_WINDOW,
188 │             });
189 │         }
190 │ 
191 │         let backoff = BACKOFF_STEPS.get(self.restart_attempts.len()).copied().unwrap_or(BACKOFF_MAX);
192 │         self.restart_attempts.push(now);
193 │         tokio::time::sleep(backoff).await;
194 │ 
195 │         // Best-effort cleanup of the crashed process before respawning — it may
196 │         // already be gone, so failures here are expected and ignored.
197 │         let _ = self.child.start_kill();
198 │         let _ = self.child.wait().await;
199 │ 
200 │         let (child, client, reader_handle) = spawn_process(&self.config).await?;
201 │         self.child = child;
202 │         self.client = client;
203 │         self.reader_handle = reader_handle;
204 │         Ok(())
205 │     }
206 │ 
207 │     /// Ends the session and guarantees the child is reaped, never left as a zombie:
208 │     /// stop reading, race a grace period against a clean exit, force-kill past it,
209 │     /// then unconditionally wait so the OS process table entry is always cleared.
210 │     pub async fn shutdown(mut self) -> Result<(), TscClientError> {
211 │         self.reader_handle.abort();
212 │         drop(self.client);
213 │ 
214 │         match tokio::time::timeout(SHUTDOWN_GRACE, self.child.wait()).await {
215 │             Ok(Ok(_status)) => Ok(()),
216 │             Ok(Err(source)) => Err(TscClientError::Reap(Arc::new(source))),
217 │             Err(_elapsed) => {
218 │                 let _ = self.child.start_kill();
219 │                 let _ = self.child.wait().await; // unconditional — never left unreaped
220 │                 Ok(())
221 │             }
222 │         }
223 │     }
224 │ }
  1 │ //! Content-Length framing, ported from `crates/cli/src/commands/lsp.rs`'s tested
  2 │ //! sync/server-role design to `tokio_util::codec`'s incremental, client-role shape.
  3 │ //! Same parsing rules, same EOF-vs-malformed-header distinction; the size cap is
  4 │ //! still checked before the body is buffered.
  5 │ //!
  6 │ //! Decoding goes through a [`Decoder`] (used via `FramedRead`) rather than a hand-
  7 │ //! rolled read loop: `tokio_util::codec` is the ecosystem-standard way to turn a byte
  8 │ //! stream into a `Stream` of frames, and it's what `Client`'s reader task and
  9 │ //! `fake-tsc`'s request loop both build on, so they can't drift on wire format.
 10 │ //! Writing has no equivalent partial-state problem — a frame is always fully formed
 11 │ //! before it's sent — so it stays a plain async function.
 12 │ 
 13 │ use bytes::BytesMut;
 14 │ use tokio::io::{AsyncWrite, AsyncWriteExt};
 15 │ use tokio_util::codec::Decoder;
 16 │ 
 17 │ use crate::error::{MalformedFrameReason, TscClientError};
 18 │ 
 19 │ /// Default cap on a single frame's declared `Content-Length`, matching
 20 │ /// `crates/cli/src/commands/lsp.rs`'s `MAX_LSP_MESSAGE_BYTES`. `tsc`'s own frames are
 21 │ /// server-controlled input with no upper bound of their own.
 22 │ pub const DEFAULT_MAX_FRAME_BYTES: usize = 16 * 1024 * 1024; // 16 MiB
 23 │ 
 24 │ /// Reject an oversized frame before its receive buffer is grown to hold it.
 25 │ pub fn check_frame_len(len: usize, cap: usize) -> Result<(), TscClientError> {
 26 │     if len > cap {
 27 │         return Err(TscClientError::OversizedFrame { declared: len, cap });
 28 │     }
 29 │     Ok(())
 30 │ }
 31 │ 
 32 │ /// Decodes Content-Length-framed messages. `decode` is called again as more bytes
 33 │ /// arrive, so header and body parsing must tolerate being invoked before a full frame
 34 │ /// — or even a full header — has arrived, returning `Ok(None)` to ask for more.
 35 │ pub struct ContentLengthDecoder {
 36 │     cap: usize,
 37 │     /// `Some(len)` once a valid header has been consumed and we're waiting for `len`
 38 │     /// more bytes of body. `None` means still scanning for the header terminator.
 39 │     pending_body_len: Option<usize>,
 40 │ }
 41 │ 
 42 │ impl ContentLengthDecoder {
 43 │     pub fn new(cap: usize) -> Self {
 44 │         Self { cap, pending_body_len: None }
 45 │     }
 46 │ 
 47 │     /// Byte offset just past `\r\n\r\n`, the header block's blank-line terminator, if
 48 │     /// it's fully buffered yet. Headers are a handful of bytes, so a full rescan on
 49 │     /// every call is not a real cost.
 50 │     fn header_end(src: &[u8]) -> Option<usize> {
 51 │         src.windows(4).position(|w| w == b"\r\n\r\n").map(|i| i + 4)
 52 │     }
 53 │ 
 54 │     /// Scans every line in a complete header block for `Content-Length` — like the
 55 │     /// sync original, an unrelated header before or after it doesn't confuse this.
 56 │     fn parse_content_length(header: &[u8]) -> Result<usize, MalformedFrameReason> {
 57 │         let text = std::str::from_utf8(header).map_err(|_| MalformedFrameReason::NoContentLengthHeader)?;
 58 │         let mut found = None;
 59 │         let mut saw_header_line = false;
 60 │         for line in text.split("\r\n") {
 61 │             if let Some(value) = line.strip_prefix("Content-Length: ") {
 62 │                 saw_header_line = true;
 63 │                 match value.trim().parse() {
 64 │                     Ok(len) => found = Some(len),
 65 │                     Err(_) => return Err(MalformedFrameReason::UnparsableContentLength),
 66 │                 }
 67 │             }
 68 │         }
 69 │         found.ok_or({
 70 │             if saw_header_line {
 71 │                 MalformedFrameReason::UnparsableContentLength
 72 │             } else {
 73 │                 MalformedFrameReason::NoContentLengthHeader
 74 │             }
 75 │         })
 76 │     }
 77 │ }
 78 │ 
 79 │ impl Decoder for ContentLengthDecoder {
 80 │     type Item = Vec<u8>;
 81 │     type Error = TscClientError;
 82 │ 
 83 │     fn decode(&mut self, src: &mut BytesMut) -> Result<Option<Vec<u8>>, TscClientError> {
 84 │         let body_len = match self.pending_body_len {
 85 │             Some(len) => len,
 86 │             None => {
 87 │                 let Some(header_end) = Self::header_end(src) else {
 88 │                     return Ok(None); // header not fully arrived yet
 89 │                 };
 90 │                 let header = src.split_to(header_end);
 91 │                 let len =
 92 │                     Self::parse_content_length(&header).map_err(|reason| TscClientError::MalformedFrame { reason })?;
 93 │                 check_frame_len(len, self.cap)?;
 94 │                 self.pending_body_len = Some(len);
 95 │                 len
 96 │             }
 97 │         };
 98 │ 
 99 │         if src.len() < body_len {
100 │             return Ok(None); // body not fully arrived yet
101 │         }
102 │ 
103 │         let body = src.split_to(body_len);
104 │         self.pending_body_len = None;
105 │         Ok(Some(body.to_vec()))
106 │     }
107 │ 
108 │     fn decode_eof(&mut self, src: &mut BytesMut) -> Result<Option<Vec<u8>>, TscClientError> {
109 │         match self.decode(src)? {
110 │             Some(frame) => Ok(Some(frame)),
111 │             None if self.pending_body_len.is_some() => {
112 │                 // A header committed us to a body length, but the stream ended before
113 │                 // delivering that many bytes.
114 │                 Err(TscClientError::MalformedFrame { reason: MalformedFrameReason::TruncatedBody })
115 │             }
116 │             // Stream ended before a full header block (blank-line terminator) ever
117 │             // arrived — zero bytes, or some header bytes with no terminator yet.
118 │             // Both are a normal, expected way for the child to close the connection.
119 │             None => Ok(None),
120 │         }
121 │     }
122 │ }
123 │ 
124 │ pub async fn write_frame<W: AsyncWrite + Unpin>(writer: &mut W, body: &[u8]) -> std::io::Result<()> {
125 │     let header = format!("Content-Length: {}\r\n\r\n", body.len());
126 │     writer.write_all(header.as_bytes()).await?;
127 │     writer.write_all(body).await?;
128 │     writer.flush().await
129 │ }
