 6 │ /// One variant family per Lifecycle-gate item (docs/type-checker-integration.md,
 7 │ /// "Gates before it ships") so a caller or test can tell failure modes apart.
 8 │ ///
 9 │ /// `Clone` on purpose, not just for this crate's own internal fan-out (one session-
10 │ /// ending failure delivered to every pending caller — see `Client::fail_all_pending`):
11 │ /// a caller-facing error type that can't be cloned forces callers to choose between
12 │ /// logging it and propagating it. The only non-`Clone` sources are `io::Error` and
13 │ /// `serde_json::Error`, `Arc`-wrapped below so cloning the rare error path is just a
14 │ /// refcount bump, never a real cost on the common (success) path.
15 │ #[derive(Debug, Clone, thiserror::Error)]
16 │ #[non_exhaustive]
17 │ pub enum TscClientError {
18 │     #[error("tsc binary not found at {path} — install `typescript@next` (npm i typescript@next) or pass an explicit path ({source})")]
19 │     SpawnFailed {
20 │         path: Utf8PathBuf,
21 │         #[source]
22 │         source: Arc<std::io::Error>,
23 │     },
24 │ 
25 │     #[error("tsc at {path} reports version {found:?}, not pinned (expected one of {expected:?})")]
26 │     UnsupportedVersion { path: Utf8PathBuf, found: String, expected: &'static [&'static str] },
27 │ 
28 │     #[error("could not determine tsc's version at {path}: {reason}")]
29 │     VersionCheckFailed { path: Utf8PathBuf, reason: String },
30 │ 
31 │     #[error("request {method:?} timed out after {after:?}")]
32 │     Timeout { method: String, after: Duration },
33 │ 
34 │     #[error("tsc exited unexpectedly (status: {status:?})")]
35 │     Crashed { status: Option<std::process::ExitStatus> },
36 │ 
37 │     #[error("tsc restarted {attempts} times within {window:?}; treating as permanently failed")]
38 │     RestartStormDetected { attempts: u32, window: Duration },
39 │ 
40 │     #[error("oversized frame: declared Content-Length {declared} exceeds the {cap}-byte cap")]
41 │     OversizedFrame { declared: usize, cap: usize },
42 │ 
43 │     #[error("malformed frame: {reason:?}")]
44 │     MalformedFrame { reason: MalformedFrameReason },
45 │ 
46 │     #[error("tsc returned a JSON-RPC error (code {code}): {message}")]
47 │     RpcError { code: i64, message: String, data: Option<serde_json::Value> },
48 │ 
49 │     #[error("session already shut down or permanently failed")]
50 │     SessionClosed,
51 │ 
52 │     #[error("I/O error writing to tsc: {0}")]
53 │     Write(#[source] Arc<std::io::Error>),
54 │ 
55 │     #[error("I/O error reading from tsc: {0}")]
56 │     Read(#[source] Arc<std::io::Error>),
57 │ 
58 │     #[error("failed to serialize a request: {0}")]
59 │     Serialize(#[source] Arc<serde_json::Error>),
60 │ 
61 │     #[error("failed to reap tsc's process: {0}")]
62 │     Reap(#[source] Arc<std::io::Error>),
63 │ }
