118	/// Owns one `tsc --api` child process across its lifetime: spawn, version check,
119	/// crash-triggered restart (bounded, to avoid a restart storm), and shutdown/reaping.
120	pub struct Supervisor {
121	    child: Child,
122	    client: Client,
123	    reader_handle: tokio::task::JoinHandle<TscClientError>,
124	    config: SupervisorConfig,
125	    restart_attempts: Vec<Instant>,
126	    /// Set once a restart-storm cap is hit. Terminal — every later call short-circuits
127	    /// without touching the process again.
128	    failed: bool,
129	}
130	
131	impl Supervisor {
132	    pub async fn spawn(config: SupervisorConfig) -> Result<Self, TscClientError> {
133	        let (child, client, reader_handle) = spawn_process(&config).await?;
134	        Ok(Self { child, client, reader_handle, config, restart_attempts: Vec::new(), failed: false })
135	    }
136	
137	    /// The current session's low-level handle. Cheap to clone. After a
138	    /// supervisor-driven restart, `Client` clones obtained *before* the restart are
139	    /// permanently `SessionClosed` — call this again to get the live one.
140	    pub fn client(&self) -> Client {
141	        self.client.clone()
142	    }
143	
144	    /// True while the current process's reader task is still running and the
145	    /// supervisor hasn't permanently failed. A crash between calls to this method and
146	    /// the next `request()` is still possible — this is a snapshot, not a guarantee.
147	    pub fn is_alive(&self) -> bool {
148	        !self.reader_handle.is_finished() && !self.failed
149	    }
