192	        assert!(
193	            matches!(
194	                result,
195	                Err(TscClientError::MalformedFrame { reason: MalformedFrameReason::UnparsableContentLength })
196	            ),
197	            "expected UnparsableContentLength, got {result:?}"
198	        );
