230	    #[test]
231	    fn a_frame_split_across_multiple_decode_calls_still_assembles() {
232	        let full = framed(&[b"hello world"]);
233	
234	        let mut decoder = ContentLengthDecoder::new(DEFAULT_MAX_FRAME_BYTES);
235	        let mut buf = BytesMut::new();
236	        // Feed one byte at a time — decode() must return Ok(None) until the whole
237	        // frame (header AND body) has arrived, never erroring on a partial header.
238	        let mut result = None;
239	        for &byte in &full {
240	            buf.extend_from_slice(&[byte]);
241	            result = decoder.decode(&mut buf).unwrap();
242	            if result.is_some() {
243	                break;
244	            }
245	        }
246	        assert_eq!(result, Some(b"hello world".to_vec()));
247	    }
