249	    /// Encodes `bodies` with the real `write_frame`, so decode tests exercise the same
250	    /// bytes the writer produces. Sync wrapper keeps these tests off `#[tokio::test]`.
251	    fn framed(bodies: &[&[u8]]) -> Vec<u8> {
252	        let runtime = tokio::runtime::Builder::new_current_thread().build().unwrap();
253	        let mut buf = Vec::new();
254	        for body in bodies {
255	            runtime.block_on(write_frame(&mut buf, body)).unwrap();
256	        }
257	        buf
258	    }
259	}
