use crate::error::{MalformedFrameReason, TscClientError};

/// Default cap on a single frame's declared `Content-Length`, matching
/// `crates/cli/src/commands/lsp.rs`'s `MAX_LSP_MESSAGE_BYTES`. `tsc`'s own frames are
